units.name:
(async () => {
  fs.mkdirSync(OUT, { recursive: true });
  const browser = await puppeteer.launch({ headless: "shell", args: ["--no-sandbox"] });
  const ctx = await browser.createBrowserContext();
  const page = await ctx.newPage();
  const errors = [];
  page.on("console", (m) => { if (m.type() === "error") errors.push(m.text()); });
  page.on("pageerror", (e) => errors.push("PAGEERR: " + e.message));
  await page.setViewport({ width: 1920, height: 1080, deviceScaleFactor: 1 });
  await page.goto("http://localhost:3000/orange-workshop", { waitUntil: "networkidle0", timeout: 60000 });
  await page.waitForSelector(".ows-gate__input", { timeout: 20000 });
  await page.type(".ows-gate__input", "orange-2026");
  await page.keyboard.press("Enter");
  await page.waitForSelector(".ows", { timeout: 20000 });
  await sleep(300);
  for (let i = 0; i < N; i++) {
    await sleep(SETTLE[i + 1] || 2650);
    await page.screenshot({ path: `${OUT}/ws-${String(i + 1).padStart(2, "0")}.png` });
    if (i < N - 1) await page.keyboard.press("ArrowRight");
  }
  console.log("ERRORS:", errors.length ? JSON.stringify([...new Set(errors)].slice(0, 20), null, 2) : "none");
  await browser.close();
})().catch()#0

