units.name:
(async () => {
  const browser = await puppeteer.launch({ headless: "shell", args: ["--no-sandbox"] });
  const page = await (await browser.createBrowserContext()).newPage();
  const errors = [];
  page.on("pageerror", (e) => errors.push("PAGEERR: " + e.message));
  await page.setViewport({ width: 1920, height: 1080, deviceScaleFactor: 2 });
  await page.goto("http://localhost:3000/orange-workshop", { waitUntil: "networkidle0", timeout: 60000 });
  await page.waitForSelector(".ows-gate__input", { timeout: 20000 });
  await page.type(".ows-gate__input", "orange-2026");
  await page.keyboard.press("Enter");
  await page.waitForSelector(".ows", { timeout: 20000 });
  await sleep(300);
  for (let i = 1; i < FRAME; i++) { await page.keyboard.press("ArrowRight"); await sleep(90); }
  await sleep(SETTLE);
  const bb = await page.evaluate(() => {
    const els = document.querySelectorAll(".ows-scene");
    for (const el of els) {
      const r = el.getBoundingClientRect();
      if (r.width > 100 && r.top > -50 && r.top < window.innerHeight) return { x: r.x, y: r.y, w: r.width, h: r.height };
    }
    return null;
  });
  if (!bb) { console.error("NO SCENE BBOX"); process.exit(2); }
  for (let k = 0; k < REGS.length; k++) {
    const [fx, fy, fw, fh] = REGS[k];
    await page.screenshot({
      path: `${OUT}/crop-${String(FRAME).padStart(2, "0")}${TAG}-${k}.png`,
      clip: { x: bb.x + bb.w * fx, y: bb.y + bb.h * fy, width: bb.w * fw, height: bb.h * fh },
    });
  }
  console.log(`OK ${REGS.length} crops · scene ${Math.round(bb.w)}x${Math.round(bb.h)} @ (${Math.round(bb.x)},${Math.round(bb.y)}) · ERRORS: ${errors.length ? errors.slice(0, 3).join(" | ") : "none"}`);
  await browser.close();
})().catch()#0

