units.name:
(async () => {
  const browser = await puppeteer.launch({ headless: "shell", args: ["--no-sandbox"] });
  const page = await (await browser.createBrowserContext()).newPage();
  const errors = [];
  page.on("pageerror", (e) => errors.push("PAGEERR: " + e.message));
  await page.setViewport({ width: VW, height: VH, deviceScaleFactor: 2 });
  await page.goto("http://localhost:3000/orange-workshop", { waitUntil: "networkidle0", timeout: 90000 });
  await page.waitForSelector(".ows-gate__input", { timeout: 20000 });
  await page.type(".ows-gate__input", "orange-2026");
  await page.keyboard.press("Enter");
  await page.waitForSelector(".ows", { timeout: 20000 });
  await sleep(300);
  for (let i = 1; i < FRAME; i++) { await page.keyboard.press("ArrowRight"); await sleep(90); }
  const t0 = Date.now();
  // derive regions from the live scene box: canvas spans the scene; window
  // x-fractions come from scene.ts geometry (console 0.055-0.345, hero
  // canvas 0.4-0.7675, rail 0.7675-0.935).
  const box = await page.evaluate(() => {
    const el = document.querySelector(".ows-scene");
    const r = el.getBoundingClientRect();
    return { x: r.x, y: r.y, w: r.width, h: r.height };
  });
  console.log(`scene box: x=${Math.round(box.x)} y=${Math.round(box.y)} w=${Math.round(box.w)} h=${Math.round(box.h)}`);
  const px = (fx) => box.x + box.w * fx;
  const REG = {
    console: { x: px(0.04), y: box.y, width: box.w * 0.32, height: box.h + 30 },
    canvas: { x: px(0.39), y: box.y, width: box.w * 0.39, height: box.h + 30 },
    rail: { x: px(0.755), y: box.y, width: box.w * 0.195, height: box.h + 30 },
    strip: { x: px(0.02), y: box.y - 10, width: box.w * 0.96, height: box.h + 45 },
  };
  for (const [label, at, regions] of BEATS) {
    const wait = at - (Date.now() - t0);
    if (wait > 0) await sleep(wait);
    for (const r of regions) {
      await page.screenshot({ path: `${OUT}/crop${TAG}-${label}-${r}.png`, clip: REG[r] });
    }
    console.log(`${label} @${Date.now() - t0}ms: ${regions.join(",")}`);
  }
  console.log("ERRORS:", errors.length ? errors.slice(0, 5).join(" | ") : "none");
  await browser.close();
  process.exit(0);
})().catch()#0

