units.name:
(async () => {
  const browser = await puppeteer.launch({ headless: "shell", args: ["--no-sandbox", "--autoplay-policy=no-user-gesture-required"] });
  const page = await (await browser.createBrowserContext()).newPage();
  const errors = [];
  page.on("pageerror", (e) => errors.push("PAGEERR: " + e.message));
  await page.setViewport({ width: 1920, height: 1080 });
  await page.goto("http://localhost:3000/orange-workshop", { waitUntil: "networkidle0", timeout: 60000 });
  await page.waitForSelector(".ows-gate__input", { timeout: 20000 });
  await page.type(".ows-gate__input", "orange-2026");
  await page.keyboard.press("Enter");
  await page.waitForSelector(".ows", { timeout: 20000 });
  await sleep(300);
  for (let i = 1; i < 11; i++) { await page.keyboard.press("ArrowRight"); await sleep(90); }
  await sleep(2200);
  const clickByText = async (txt) => page.evaluate((t) => {
    const b = [...document.querySelectorAll("button")].find((x) => x.textContent && x.textContent.includes(t));
    if (b) b.click();
    return !!b;
  }, txt);
  for (const [card, tag] of [["Sales agent", "sales"], ["In-shop agent", "inshop"], ["Reviews agent", "reviews"], ["LOOP", "loop"]]) {
    await clickByText(card);
    await sleep(350);
    const ok = await clickByText("Watch the demo");
    await sleep(2400);
    const st = await page.evaluate(() => {
      const v = document.querySelector(".ows-lightbox video");
      return v ? { t: +v.currentTime.toFixed(1), w: v.videoWidth, paused: v.paused } : null;
    });
    console.log(tag, "btn:", ok, JSON.stringify(st));
    await page.screenshot({ path: `${OUT}/video-${tag}.png` });
    await page.keyboard.press("Escape");
    await sleep(400);
  }
  console.log(`ERRORS: ${errors.length ? errors.slice(0, 3).join(" | ") : "none"}`);
  await browser.close();
})().catch()#0

